import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;
import okhttp3.OkHttpClient;

@Slf4j
@PluginDescriptor(
	name = "Material Planner",
	description = "Remembers your bank and other storage, and plans the materials for any recipe",
	internalName = "material-planner",
	legacyDataDirectory = "material-planner",
	tags = {"bank", "memory", "recipe", "materials", "shopping", "skilling", "sailing", "storage"}
)
public class MaterialPlannerPlugin extends Plugin implements PanelHost
{
	private static final String BANK_FILLER = "Bank filler";

	/** Game container id → where we file its contents. */
	private static final Map<Integer, Location> CONTAINERS = new HashMap<>();

	static
	{
		CONTAINERS.put(InventoryID.INV, Location.INVENTORY);
		CONTAINERS.put(InventoryID.WORN, Location.WORN);
		CONTAINERS.put(InventoryID.BANK, Location.BANK);
		CONTAINERS.put(InventoryID.SEED_VAULT, Location.SEED_VAULT);
		CONTAINERS.put(InventoryID.SEED_BOX, Location.SEED_BOX);
		CONTAINERS.put(InventoryID.LOOTING_BAG, Location.LOOTING_BAG);
		CONTAINERS.put(InventoryID.INV_GROUP_TEMP, Location.GROUP_STORAGE);
	}

	private static final int[] POUCH_TYPE_VARBITS = {
		VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
		VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6
	};
	private static final int[] POUCH_QTY_VARBITS = {
		VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2, VarbitID.RUNE_POUCH_QUANTITY_3,
		VarbitID.RUNE_POUCH_QUANTITY_4, VarbitID.RUNE_POUCH_QUANTITY_5, VarbitID.RUNE_POUCH_QUANTITY_6
	};
	private static final Set<Integer> POUCH_VARBITS = new HashSet<>();

	static
	{
		Arrays.stream(POUCH_TYPE_VARBITS).forEach(POUCH_VARBITS::add);
		Arrays.stream(POUCH_QTY_VARBITS).forEach(POUCH_VARBITS::add);
	}

	/** Settings whose change should redraw the panel. */
	private static final Set<String> DISPLAY_KEYS = new HashSet<>(Arrays.asList(
		"expandRecipes", "costMode", "levelCheck", "hideUnmet", "countWorn", "countOtherStorage",
		"highlightBank", "highlightColor"));

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BankHighlightOverlay bankOverlay;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private MaterialPlannerConfig config;

	@Inject
	private Gson gson;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private ScheduledExecutorService executor;

	private ItemStore store;
	private RecipeRepository recipes;
	private MaterialPlannerPanel panel;
	private NavigationButton navButton;

	private final Map<String, Integer> levels = new ConcurrentHashMap<>();
	/** Boat name of the cargo hold window currently open, or null when it's closed. */
	private String openCargoBoat;
	private String lastCargoSignature;
	private volatile boolean ironman;

	@Provides
	MaterialPlannerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MaterialPlannerConfig.class);
	}

	@Override
	protected void startUp()
	{
		store = new ItemStore(configManager, gson);
		Filepath dataDir = null;
		try
		{
			dataDir = getPluginDirectory();
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Plugin data directory unavailable; recipes won't be cached", e);
		}
		recipes = new RecipeRepository(gson, okHttpClient, dataDir);
		panel = new MaterialPlannerPanel(itemManager, store, recipes, configManager, gson, config, this,
			() -> loadRecipes(true));

		BufferedImage icon = ImageUtil.loadImageResource(MaterialPlannerPlugin.class, "panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Material Planner")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(bankOverlay);

		store.loadProfile();
		loadRecipes(false);

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(this::captureLoggedInState);
		}
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(bankOverlay);
		bankOverlay.setNeeded(new HashSet<>());
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
		store = null;
		recipes = null;
		levels.clear();
	}

	/**
	 * Client thread. Reads everything available right now: open containers, levels, account type, rune pouch.
	 */
	private void captureLoggedInState()
	{
		for (Map.Entry<Integer, Location> e : CONTAINERS.entrySet())
		{
			ItemContainer c = client.getItemContainer(e.getKey());
			if (c != null)
			{
				record(e.getValue(), c);
			}
		}
		for (Skill s : Skill.values())
		{
			levels.put(s.getName().toLowerCase(Locale.ROOT), client.getRealSkillLevel(s));
		}
		ironman = client.getVarbitValue(VarbitID.IRONMAN) > 0;
		updateRunePouch();
		refreshPanelSettings();
	}

	private void loadRecipes(boolean force)
	{
		executor.execute(() ->
		{
			RecipeRepository repo = recipes;
			if (repo == null)
			{
				return;
			}
			SwingUtilities.invokeLater(this::refreshPanelRecipes);
			repo.load(config.wikiRecipes(), config.refreshDays(), force);
			SwingUtilities.invokeLater(this::refreshPanelRecipes);
		});
	}

	private void refreshPanelRecipes()
	{
		if (panel != null)
		{
			panel.onRecipesLoaded();
		}
	}

	private void refreshPanelSettings()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.onSettingsChanged();
			}
		});
	}

	// --- containers ------------------------------------------------------------------------------

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		Location loc = CONTAINERS.get(event.getContainerId());
		if (loc == null)
		{
			return;
		}
		record(loc, event.getItemContainer());
		if (loc == Location.INVENTORY)
		{
			// Rune pouch only counts while the pouch itself is carried
			updateRunePouch();
		}
	}

	/**
	 * Client thread.
	 */
	private void record(Location loc, ItemContainer container)
	{
		List<StoredItem> items = toStoredItems(container);
		// An empty bank event almost always means "not loaded", not an empty bank
		if (loc == Location.BANK && items.isEmpty())
		{
			return;
		}
		store.update(loc, items);
	}

	/**
	 * Must run on the client thread (item compositions).
	 */
	private List<StoredItem> toStoredItems(ItemContainer container)
	{
		List<int[]> stacks = new ArrayList<>();
		if (container != null)
		{
			for (Item item : container.getItems())
			{
				stacks.add(new int[]{item.getId(), item.getQuantity()});
			}
		}
		return toStoredItems(stacks);
	}

	/**
	 * Must run on the client thread.
	 *
	 * @param stacks pairs of {item id, quantity}
	 */
	private List<StoredItem> toStoredItems(List<int[]> stacks)
	{
		List<StoredItem> out = new ArrayList<>();
		for (int[] stack : stacks)
		{
			int itemId = stack[0];
			int qty = stack[1];
			if (itemId <= 0 || qty <= 0)
			{
				continue;
			}
			ItemComposition comp = itemManager.getItemComposition(itemId);
			if (comp.getPlaceholderTemplateId() != -1)
			{
				continue;
			}
			int canonical = itemManager.canonicalize(itemId);
			String name = itemManager.getItemComposition(canonical).getName();
			if (name == null || name.equals("null") || name.equals(BANK_FILLER))
			{
				continue;
			}
			out.add(new StoredItem(canonical, name, qty));
		}
		return out;
	}

	/**
	 * Client thread. Rune pouch contents live in varbits rather than an item container.
	 */
	private void updateRunePouch()
	{
		if (store == null)
		{
			return;
		}
		List<StoredItem> runes = new ArrayList<>();
		if (carryingRunePouch())
		{
			EnumComposition runeEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
			for (int i = 0; i < POUCH_TYPE_VARBITS.length; i++)
			{
				int type = client.getVarbitValue(POUCH_TYPE_VARBITS[i]);
				int qty = client.getVarbitValue(POUCH_QTY_VARBITS[i]);
				if (type <= 0 || qty <= 0 || runeEnum == null)
				{
					continue;
				}
				int itemId = runeEnum.getIntValue(type);
				if (itemId <= 0)
				{
					continue;
				}
				runes.add(new StoredItem(itemId, itemManager.getItemComposition(itemId).getName(), qty));
			}
		}
		store.update(Location.RUNE_POUCH, runes);
	}

	private boolean carryingRunePouch()
	{
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		if (inv == null)
		{
			return false;
		}
		for (Item item : inv.getItems())
		{
			if (item.getId() > 0)
			{
				String name = itemManager.getItemComposition(item.getId()).getName();
				if (name != null && name.toLowerCase(Locale.ROOT).contains("rune pouch"))
				{
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * Cargo holds are read straight from the cargo hold window while it's open: the window's title
	 * names the boat, which lets each boat keep its own snapshot.
	 */
	@Subscribe
	public void onGameTick(GameTick event)
	{
		Widget itemsWidget = client.getWidget(InterfaceID.SailingBoatCargohold.ITEMS);
		if (itemsWidget == null || itemsWidget.isHidden())
		{
			openCargoBoat = null;
			lastCargoSignature = null;
			return;
		}
		if (openCargoBoat == null)
		{
			openCargoBoat = findCargoBoatName();
		}

		List<int[]> stacks = new ArrayList<>();
		StringBuilder sig = new StringBuilder(openCargoBoat);
		Widget[] children = itemsWidget.getDynamicChildren();
		if (children != null)
		{
			for (Widget w : children)
			{
				if (w != null && !w.isHidden() && w.getItemId() > 0 && w.getItemQuantity() > 0)
				{
					stacks.add(new int[]{w.getItemId(), w.getItemQuantity()});
					sig.append('|').append(w.getItemId()).append('x').append(w.getItemQuantity());
				}
			}
		}
		// Only save when the contents change
		if (sig.toString().equals(lastCargoSignature))
		{
			return;
		}
		lastCargoSignature = sig.toString();
		store.update(store.cargoSlotFor(openCargoBoat), toStoredItems(stacks));
	}

	private String findCargoBoatName()
	{
		String title = findText(client.getWidget(InterfaceID.SailingBoatCargohold.UNIVERSE), "cargo hold", 0);
		if (title != null)
		{
			int colon = title.indexOf(':');
			String name = Text.removeTags(colon >= 0 ? title.substring(colon + 1) : title).trim();
			if (!name.isEmpty())
			{
				return name;
			}
		}
		return "Boat";
	}

	/**
	 * Depth-first search of a widget tree for text containing the given phrase.
	 */
	private static String findText(Widget w, String phrase, int depth)
	{
		if (w == null || depth > 6)
		{
			return null;
		}
		String text = w.getText();
		if (text != null && Text.removeTags(text).toLowerCase(Locale.ROOT).contains(phrase))
		{
			return text;
		}
		for (Widget[] group : new Widget[][]{w.getStaticChildren(), w.getDynamicChildren(), w.getNestedChildren()})
		{
			if (group == null)
			{
				continue;
			}
			for (Widget c : group)
			{
				String found = findText(c, phrase, depth + 1);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		int id = event.getVarbitId();
		if (POUCH_VARBITS.contains(id))
		{
			updateRunePouch();
		}
		else if (id == VarbitID.IRONMAN)
		{
			boolean now = event.getValue() > 0;
			if (now != ironman)
			{
				ironman = now;
				refreshPanelSettings();
			}
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		String key = event.getSkill().getName().toLowerCase(Locale.ROOT);
		Integer prev = levels.put(key, event.getLevel());
		// Fires on every xp drop; only redraw when a level actually changes
		if (prev == null || prev != event.getLevel())
		{
			refreshPanelSettings();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		store.loadProfile();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			store.clearLive();
			levels.clear();
			ironman = false;
			refreshPanelSettings();
		}
		else if (event.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(this::captureLoggedInState);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!MaterialPlannerConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if ("wikiRecipes".equals(event.getKey()))
		{
			loadRecipes(false);
		}
		else if (DISPLAY_KEYS.contains(event.getKey()))
		{
			refreshPanelSettings();
		}
	}

	// --- PanelHost -------------------------------------------------------------------------------

	@Override
	public int realLevel(String skill)
	{
		if (skill == null)
		{
			return -1;
		}
		String key = skill.toLowerCase(Locale.ROOT);
		// The wiki says "Runecrafting"; RuneLite's skill is "Runecraft"
		if (key.equals("runecrafting"))
		{
			key = "runecraft";
		}
		return levels.getOrDefault(key, -1);
	}

	@Override
	public CostMode effectiveCostMode()
	{
		CostMode mode = config.costMode();
		if (mode == CostMode.AUTO)
		{
			return ironman ? CostMode.COINS_ONLY : CostMode.GE_PRICES;
		}
		return mode;
	}

	@Override
	public void onPlanChanged(Set<String> bankNeeded)
	{
		bankOverlay.setNeeded(bankNeeded);
	}

	// --- "Check bank" menu option ----------------------------------------------------------------

	/**
	 * Adds "Check bank" next to Examine on inventory items and ground items.
	 */
	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!config.checkBankMenu())
		{
			return;
		}

		MenuEntry entry = event.getMenuEntry();
		if (!"Examine".equals(entry.getOption()))
		{
			return;
		}

		final int itemId;
		if (entry.getType() == MenuAction.EXAMINE_ITEM_GROUND)
		{
			itemId = entry.getIdentifier();
		}
		else if ((entry.getParam1() >>> 16) == InterfaceID.INVENTORY && entry.getItemId() > 0)
		{
			itemId = entry.getItemId();
		}
		else
		{
			return;
		}

		client.getMenu().createMenuEntry(-1)
			.setOption("Check bank")
			.setTarget(entry.getTarget())
			.setType(MenuAction.RUNELITE)
			.onClick(e -> checkBank(itemId));
	}

	private void checkBank(int itemId)
	{
		int canonical = itemManager.canonicalize(itemId);
		String name = itemManager.getItemComposition(canonical).getName();

		String msg;
		if (!store.hasBankSnapshot())
		{
			msg = "Material Planner: no bank snapshot yet. Open your bank once to record it.";
		}
		else
		{
			Counts c = store.countById(canonical);
			NumberFormat nf = NumberFormat.getIntegerInstance();
			StringBuilder sb = new StringBuilder(name)
				.append(" - Bank: <col=ff9040>").append(nf.format(c.bank())).append("</col>")
				.append(", Inventory: ").append(nf.format(c.get(Location.INVENTORY)));
			for (Map.Entry<Location, Long> e : c.asMap().entrySet())
			{
				Location loc = e.getKey();
				if (loc != Location.BANK && loc != Location.INVENTORY)
				{
					sb.append(", ").append(store.label(loc)).append(": ").append(nf.format(e.getValue()));
				}
			}
			sb.append(" <col=7f7f7f>(bank as of ").append(MaterialPlannerPanel.ago(store.getBankTime())).append(")</col>");
			msg = sb.toString();
		}
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", msg, null);
	}
}

package com.materialplanner.items;

import java.util.EnumMap;
import java.util.Map;

/**
 * How many of one item are in each tracked location.
 */
public final class Counts
{
	private final EnumMap<Location, Long> byLocation = new EnumMap<>(Location.class);

	public void add(Location loc, long qty)
	{
		byLocation.merge(loc, qty, Long::sum);
	}

	public long get(Location loc)
	{
		return byLocation.getOrDefault(loc, 0L);
	}

	public Map<Location, Long> asMap()
	{
		return byLocation;
	}

	/**
	 * On you right now. Worn items only count when the user allows it.
	 */
	public long carried(boolean includeWorn)
	{
		long sum = 0;
		for (Map.Entry<Location, Long> e : byLocation.entrySet())
		{
			if (e.getKey().isCarried() && (includeWorn || e.getKey() != Location.WORN))
			{
				sum += e.getValue();
			}
		}
		return sum;
	}

	public long bank()
	{
		return get(Location.BANK);
	}

	public long other()
	{
		long sum = 0;
		for (Map.Entry<Location, Long> e : byLocation.entrySet())
		{
			if (e.getKey().isOtherStorage())
			{
				sum += e.getValue();
			}
		}
		return sum;
	}

	public long total(boolean includeWorn, boolean includeOther)
	{
		return carried(includeWorn) + bank() + (includeOther ? other() : 0);
	}
}

package com.materialplanner.items;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Last-seen contents of every tracked location. Storage snapshots are saved per account;
 * inventory, equipment and rune pouch are live only.
 */
@Slf4j
public class ItemStore
{
	private static final String GROUP = "materialplanner";
	private static final Type LIST_TYPE = new TypeToken<List<StoredItem>>()
	{
	}.getType();

	/**
	 * One stack summed across locations, for the "All storage" view.
	 */
	public static final class Aggregate
	{
		public final int id;
		public final String name;
		public final Counts counts = new Counts();

		Aggregate(int id, String name)
		{
			this.id = id;
			this.name = name;
		}
	}

	private final ConfigManager configManager;
	private final Gson gson;
	private final List<Runnable> listeners = new CopyOnWriteArrayList<>();

	private static final String KEY_CARGO_NAMES = "cargoBoatNames";
	private static final Type NAMES_TYPE = new TypeToken<Map<String, String>>()
	{
	}.getType();
	private static final Location[] CARGO_SLOTS = {
		Location.CARGO_HOLD_1, Location.CARGO_HOLD_2, Location.CARGO_HOLD_3, Location.CARGO_HOLD_4, Location.CARGO_HOLD_5
	};

	private final EnumMap<Location, Map<Integer, StoredItem>> items = new EnumMap<>(Location.class);
	/** Cargo hold slot → boat name read from the cargo hold window title. */
	private final EnumMap<Location, String> cargoNames = new EnumMap<>(Location.class);
	private final EnumMap<Location, Long> times = new EnumMap<>(Location.class);

	public ItemStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public void addListener(Runnable r)
	{
		listeners.add(r);
	}

	private void fire()
	{
		listeners.forEach(Runnable::run);
	}

	// The bank keeps its original keys so snapshots from earlier versions still load
	private static String itemsKey(Location loc)
	{
		return loc == Location.BANK ? "bankSnapshot" : "snapshot." + loc.name();
	}

	private static String timeKey(Location loc)
	{
		return loc == Location.BANK ? "bankSnapshotTime" : "snapshotTime." + loc.name();
	}

	/**
	 * Load saved snapshots for the current RuneScape profile and forget live containers.
	 */
	public void loadProfile()
	{
		EnumMap<Location, Map<Integer, StoredItem>> loaded = new EnumMap<>(Location.class);
		EnumMap<Location, Long> loadedTimes = new EnumMap<>(Location.class);
		for (Location loc : Location.values())
		{
			if (!loc.isPersistent())
			{
				continue;
			}
			String json = configManager.getRSProfileConfiguration(GROUP, itemsKey(loc));
			if (json == null || json.isEmpty())
			{
				continue;
			}
			try
			{
				List<StoredItem> list = gson.fromJson(json, LIST_TYPE);
				Map<Integer, StoredItem> m = new LinkedHashMap<>();
				if (list != null)
				{
					for (StoredItem it : list)
					{
						m.put(it.getId(), it);
					}
				}
				loaded.put(loc, m);
				String t = configManager.getRSProfileConfiguration(GROUP, timeKey(loc));
				loadedTimes.put(loc, t == null ? 0L : Long.parseLong(t));
			}
			catch (JsonSyntaxException | NumberFormatException e)
			{
				log.warn("Could not read saved snapshot for {}", loc, e);
			}
		}
		EnumMap<Location, String> names = new EnumMap<>(Location.class);
		String namesJson = configManager.getRSProfileConfiguration(GROUP, KEY_CARGO_NAMES);
		if (namesJson != null && !namesJson.isEmpty())
		{
			try
			{
				Map<String, String> m = gson.fromJson(namesJson, NAMES_TYPE);
				if (m != null)
				{
					for (Map.Entry<String, String> e : m.entrySet())
					{
						names.put(Location.valueOf(e.getKey()), e.getValue());
					}
				}
			}
			catch (JsonSyntaxException | IllegalArgumentException e)
			{
				log.warn("Could not read cargo hold names", e);
			}
		}

		synchronized (this)
		{
			items.clear();
			times.clear();
			cargoNames.clear();
			items.putAll(loaded);
			times.putAll(loadedTimes);
			cargoNames.putAll(names);
		}
		fire();
	}

	/**
	 * The storage slot for a boat's cargo hold, assigned the first time that boat's hold is seen.
	 */
	public Location cargoSlotFor(String boatName)
	{
		Location slot = null;
		synchronized (this)
		{
			for (Location loc : CARGO_SLOTS)
			{
				if (boatName.equalsIgnoreCase(cargoNames.get(loc)))
				{
					return loc;
				}
			}
			for (Location loc : CARGO_SLOTS)
			{
				if (!cargoNames.containsKey(loc))
				{
					slot = loc;
					break;
				}
			}
			if (slot == null)
			{
				// More than five boats seen; reuse the last slot
				slot = CARGO_SLOTS[CARGO_SLOTS.length - 1];
			}
			cargoNames.put(slot, boatName);
		}
		Map<String, String> save = new HashMap<>();
		synchronized (this)
		{
			for (Map.Entry<Location, String> e : cargoNames.entrySet())
			{
				save.put(e.getKey().name(), e.getValue());
			}
		}
		configManager.setRSProfileConfiguration(GROUP, KEY_CARGO_NAMES, gson.toJson(save, NAMES_TYPE));
		return slot;
	}

	/**
	 * Display name, using the boat's name for cargo holds.
	 */
	public synchronized String label(Location loc)
	{
		String boat = cargoNames.get(loc);
		return boat == null ? loc.getLabel() : "Cargo hold: " + boat;
	}

	public synchronized String shortLabel(Location loc)
	{
		String boat = cargoNames.get(loc);
		return boat == null ? loc.getShortLabel() : boat;
	}

	public void update(Location location, List<StoredItem> list)
	{
		Map<Integer, StoredItem> map = new LinkedHashMap<>();
		for (StoredItem it : list)
		{
			StoredItem prev = map.get(it.getId());
			map.put(it.getId(), prev == null ? it
				: new StoredItem(it.getId(), it.getName(), prev.getQuantity() + it.getQuantity()));
		}

		long now = System.currentTimeMillis();
		synchronized (this)
		{
			items.put(location, map);
			times.put(location, now);
		}

		if (location.isPersistent())
		{
			configManager.setRSProfileConfiguration(GROUP, itemsKey(location), gson.toJson(new ArrayList<>(map.values())));
			configManager.setRSProfileConfiguration(GROUP, timeKey(location), String.valueOf(now));
		}
		fire();
	}

	/**
	 * Forget inventory, equipment and rune pouch (logout / account switch). Saved storage is kept.
	 */
	public void clearLive()
	{
		synchronized (this)
		{
			for (Location loc : Location.values())
			{
				if (!loc.isPersistent())
				{
					items.remove(loc);
					times.remove(loc);
				}
			}
		}
		fire();
	}

	public synchronized boolean hasSnapshot(Location loc)
	{
		return times.getOrDefault(loc, 0L) > 0;
	}

	public synchronized long getTime(Location loc)
	{
		return times.getOrDefault(loc, 0L);
	}

	public boolean hasBankSnapshot()
	{
		return hasSnapshot(Location.BANK);
	}

	public long getBankTime()
	{
		return getTime(Location.BANK);
	}

	public synchronized List<StoredItem> getItems(Location loc)
	{
		Map<Integer, StoredItem> m = items.get(loc);
		return m == null ? new ArrayList<>() : new ArrayList<>(m.values());
	}

	/**
	 * Persistent locations that have been recorded at least once.
	 */
	public synchronized List<Location> recordedStorage()
	{
		List<Location> out = new ArrayList<>();
		for (Location loc : Location.values())
		{
			if (loc.isPersistent() && times.getOrDefault(loc, 0L) > 0)
			{
				out.add(loc);
			}
		}
		return out;
	}

	/**
	 * Everything in saved storage (not on you), summed by item.
	 */
	public synchronized List<Aggregate> allStorage()
	{
		Map<Integer, Aggregate> out = new LinkedHashMap<>();
		for (Map.Entry<Location, Map<Integer, StoredItem>> e : items.entrySet())
		{
			if (!e.getKey().isPersistent())
			{
				continue;
			}
			for (StoredItem it : e.getValue().values())
			{
				out.computeIfAbsent(it.getId(), id -> new Aggregate(id, it.getName())).counts.add(e.getKey(), it.getQuantity());
			}
		}
		return new ArrayList<>(out.values());
	}

	public synchronized Counts countById(int canonicalId)
	{
		Counts c = new Counts();
		for (Map.Entry<Location, Map<Integer, StoredItem>> e : items.entrySet())
		{
			StoredItem it = e.getValue().get(canonicalId);
			if (it != null)
			{
				c.add(e.getKey(), it.getQuantity());
			}
		}
		return c;
	}

	/**
	 * Recipes reference materials by name, so count every stack whose name matches (case-insensitive).
	 */
	public synchronized Map<String, Counts> countsByName()
	{
		Map<String, Counts> out = new HashMap<>();
		for (Map.Entry<Location, Map<Integer, StoredItem>> e : items.entrySet())
		{
			for (StoredItem it : e.getValue().values())
			{
				out.computeIfAbsent(normalize(it.getName()), k -> new Counts()).add(e.getKey(), it.getQuantity());
			}
		}
		return out;
	}

	/**
	 * Find an item id for a name from anything we have seen. Used for icons of untradeable items.
	 */
	public synchronized int idForName(String name)
	{
		String n = normalize(name);
		for (Map<Integer, StoredItem> m : items.values())
		{
			for (StoredItem it : m.values())
			{
				if (normalize(it.getName()).equals(n))
				{
					return it.getId();
				}
			}
		}
		return -1;
	}

	public static String normalize(String name)
	{
		return name == null ? "" : name.trim().toLowerCase(Locale.ROOT);
	}
}

package com.materialplanner.items;

/**
 * Every place the plugin tracks items. "Carried" locations count as already on you;
 * "persistent" ones are saved per account and survive restarts.
 */
public enum Location
{
	INVENTORY("Inventory", "Inv", true, false),
	WORN("Worn", "Worn", true, false),
	RUNE_POUCH("Rune pouch", "Pouch", true, false),
	BANK("Bank", "Bank", false, true),
	SEED_VAULT("Seed vault", "Vault", false, true),
	SEED_BOX("Seed box", "Seed box", false, true),
	LOOTING_BAG("Looting bag", "Loot bag", false, true),
	GROUP_STORAGE("Group storage", "Group", false, true),
	CARGO_HOLD_1("Cargo hold (boat 1)", "Hold 1", false, true),
	CARGO_HOLD_2("Cargo hold (boat 2)", "Hold 2", false, true),
	CARGO_HOLD_3("Cargo hold (boat 3)", "Hold 3", false, true),
	CARGO_HOLD_4("Cargo hold (boat 4)", "Hold 4", false, true),
	CARGO_HOLD_5("Cargo hold (boat 5)", "Hold 5", false, true);

	private final String label;
	private final String shortLabel;
	private final boolean carried;
	private final boolean persistent;

	Location(String label, String shortLabel, boolean carried, boolean persistent)
	{
		this.label = label;
		this.shortLabel = shortLabel;
		this.carried = carried;
		this.persistent = persistent;
	}

	public String getLabel()
	{
		return label;
	}

	public String getShortLabel()
	{
		return shortLabel;
	}

	public boolean isCarried()
	{
		return carried;
	}

	public boolean isPersistent()
	{
		return persistent;
	}

	/**
	 * Storage that isn't the bank and isn't on you.
	 */
	public boolean isOtherStorage()
	{
		return !carried && this != BANK;
	}
}

package com.materialplanner.items;

/**
 * One stack of an item: canonical (un-noted) item id, its name at capture time, and quantity.
 */
public final class StoredItem
{
	private final int id;
	private final String name;
	private final long quantity;

	public StoredItem(int id, String name, long quantity)
	{
		this.id = id;
		this.name = name;
		this.quantity = quantity;
	}

	public int getId()
	{
		return id;
	}

	public String getName()
	{
		return name;
	}

	public long getQuantity()
	{
		return quantity;
	}
}

package com.materialplanner.recipes;

import com.materialplanner.items.Counts;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Turns "make these recipes" into a material tree.
 * <p>
 * For every material it first uses what you already own (on you, then bank, then other storage), and only
 * plans to craft what is still missing, recursing into that recipe's ingredients. Stock is shared across
 * the whole plan, so two recipes needing the same planks don't both count the same planks.
 * <p>
 * Pure logic with no RuneLite dependencies, so it can be tested on its own.
 */
public final class Planner
{
	/**
	 * Method override meaning "don't craft this, I'll get it another way".
	 */
	public static final String NO_MAKE = "-";

	private static final Set<String> NEVER_EXPAND = new HashSet<>(Collections.singletonList("coins"));

	public enum Status
	{
		/** Enough carried right now. */
		ON_YOU,
		/** Enough once withdrawn from bank or other storage. */
		IN_STORAGE,
		/** Some or all of it will be crafted; see children. */
		MAKE,
		/** Not enough and not craftable (or crafting disabled). */
		SHORT
	}

	public static final class Options
	{
		public boolean expand = true;
		public int maxDepth = 8;
		public boolean includeWorn = true;
		public boolean includeOther = true;
		/** normalized material name → recipe key to use, or NO_MAKE */
		public Map<String, String> methods = new HashMap<>();
	}

	public static final class Node
	{
		public final String name;
		public final String key;
		public final long need;
		public final int depth;
		public long fromCarried;
		public long fromBank;
		public long fromOther;
		public long fromSurplus;
		public Recipe via;
		public long crafts;
		public long shortBy;
		public List<Recipe> alternatives = Collections.emptyList();
		public final List<Node> children = new ArrayList<>();

		Node(String name, long need, int depth)
		{
			this.name = name;
			this.key = normalize(name);
			this.need = need;
			this.depth = depth;
		}

		public long fromStock()
		{
			return fromCarried + fromBank + fromOther;
		}

		public Status status()
		{
			if (shortBy > 0)
			{
				return Status.SHORT;
			}
			if (via != null && crafts > 0)
			{
				return Status.MAKE;
			}
			if (fromBank + fromOther > 0)
			{
				return Status.IN_STORAGE;
			}
			return Status.ON_YOU;
		}

		public boolean subtreeShort()
		{
			if (shortBy > 0)
			{
				return true;
			}
			for (Node c : children)
			{
				if (c.subtreeShort())
				{
					return true;
				}
			}
			return false;
		}

		/**
		 * Stable id for remembering which rows the user collapsed.
		 */
		public String path(String parentPath)
		{
			return parentPath + "/" + key;
		}
	}

	public static final class Plan
	{
		public final List<Node> roots = new ArrayList<>();
		/** Raw materials still missing after crafting what can be crafted (display name → qty). */
		public final Map<String, Long> shortages = new LinkedHashMap<>();
		/** Items the plan takes from the bank, by normalized name. Drives bank highlighting. */
		public final Map<String, Long> fromBank = new HashMap<>();
		/** Items the plan takes from other storage, by normalized name. */
		public final Map<String, Long> fromOther = new HashMap<>();
		public long coinsNeeded;
		public long coinsAvailable;
		public int ready;
		public int toMake;
		public int shortCount;
	}

	private final Map<String, List<Recipe>> byOutput;
	private final Map<String, Counts> stock;
	private final Options opt;
	/** Remaining unallocated stock per item: [carried, bank, other]. */
	private final Map<String, long[]> remaining = new HashMap<>();
	/** Extra output from crafts that make more than needed (e.g. 15 arrows per action). */
	private final Map<String, Long> surplus = new HashMap<>();

	private Planner(Map<String, List<Recipe>> byOutput, Map<String, Counts> stock, Options opt)
	{
		this.byOutput = byOutput;
		this.stock = stock;
		this.opt = opt;
	}

	/**
	 * @param selections recipe → number of times it will be made, in display order
	 * @param byOutput   all recipes indexed by normalized output name
	 * @param stock      item counts indexed by normalized name
	 */
	public static Plan plan(Map<Recipe, Integer> selections, Map<String, List<Recipe>> byOutput,
		Map<String, Counts> stock, Options opt)
	{
		Planner p = new Planner(byOutput, stock, opt);
		Plan plan = new Plan();

		// Sum top-level needs first so shared materials are allocated once
		Map<String, Long> need = new LinkedHashMap<>();
		Map<String, String> display = new HashMap<>();
		Set<String> selectedOutputs = new HashSet<>();
		for (Map.Entry<Recipe, Integer> e : selections.entrySet())
		{
			selectedOutputs.add(normalize(e.getKey().name));
			for (Recipe.Material m : e.getKey().materials)
			{
				String k = normalize(m.name);
				need.merge(k, (long) m.quantity * e.getValue(), Long::sum);
				display.putIfAbsent(k, m.name);
			}
		}

		for (Map.Entry<String, Long> e : need.entrySet())
		{
			Node root = p.expand(display.get(e.getKey()), e.getValue(), 0, selectedOutputs);
			plan.roots.add(root);
			if (root.subtreeShort())
			{
				plan.shortCount++;
			}
			else if (containsMake(root))
			{
				plan.toMake++;
			}
			else
			{
				plan.ready++;
			}
		}

		for (Node r : plan.roots)
		{
			p.collect(r, plan);
		}
		Counts coins = stock.get("coins");
		plan.coinsAvailable = coins == null ? 0 : coins.total(opt.includeWorn, opt.includeOther);
		return plan;
	}

	private Node expand(String name, long need, int depth, Set<String> ancestry)
	{
		Node n = new Node(name, need, depth);
		long left = need;

		long s = surplus.getOrDefault(n.key, 0L);
		if (s > 0)
		{
			n.fromSurplus = Math.min(s, left);
			surplus.put(n.key, s - n.fromSurplus);
			left -= n.fromSurplus;
		}

		long[] r = remaining.computeIfAbsent(n.key, this::initialStock);
		n.fromCarried = take(r, 0, left);
		left -= n.fromCarried;
		n.fromBank = take(r, 1, left);
		left -= n.fromBank;
		n.fromOther = take(r, 2, left);
		left -= n.fromOther;

		if (left <= 0)
		{
			return n;
		}

		List<Recipe> candidates = candidates(n.key, ancestry);
		n.alternatives = candidates;
		Recipe chosen = opt.expand && depth < opt.maxDepth && !NEVER_EXPAND.contains(n.key)
			? choose(n.key, candidates) : null;

		if (chosen == null)
		{
			n.shortBy = left;
			return n;
		}

		long out = Math.max(1, chosen.outputQuantity);
		long crafts = (left + out - 1) / out;
		long extra = crafts * out - left;
		if (extra > 0)
		{
			surplus.merge(n.key, extra, Long::sum);
		}
		n.via = chosen;
		n.crafts = crafts;

		Set<String> childAncestry = new HashSet<>(ancestry);
		childAncestry.add(n.key);
		for (Recipe.Material m : chosen.materials)
		{
			n.children.add(expand(m.name, m.quantity * crafts, depth + 1, childAncestry));
		}
		return n;
	}

	private long[] initialStock(String key)
	{
		Counts c = stock.get(key);
		if (c == null)
		{
			return new long[3];
		}
		return new long[]{c.carried(opt.includeWorn), c.bank(), opt.includeOther ? c.other() : 0};
	}

	private static long take(long[] pool, int idx, long want)
	{
		if (want <= 0)
		{
			return 0;
		}
		long t = Math.min(pool[idx], want);
		pool[idx] -= t;
		return t;
	}

	/**
	 * Recipes that produce this item without needing anything already being made higher up the tree.
	 */
	private List<Recipe> candidates(String key, Set<String> ancestry)
	{
		List<Recipe> all = byOutput.getOrDefault(key, Collections.emptyList());
		List<Recipe> out = new ArrayList<>();
		for (Recipe r : all)
		{
			boolean loops = false;
			for (Recipe.Material m : r.materials)
			{
				String mk = normalize(m.name);
				if (mk.equals(key) || ancestry.contains(mk))
				{
					loops = true;
					break;
				}
			}
			if (!loops)
			{
				out.add(r);
			}
		}
		out.sort(DEFAULT_ORDER);
		return out;
	}

	/**
	 * Preference when the user hasn't picked a method: plain crafting before spells, fewer distinct
	 * ingredients, then fewer ingredients per item made.
	 */
	static final Comparator<Recipe> DEFAULT_ORDER = Comparator
		.comparing((Recipe r) -> r.usesSkill("Magic"))
		.thenComparingInt(r -> r.materials.size())
		.thenComparingDouble(r -> (double) r.totalMaterialQuantity() / Math.max(1, r.outputQuantity))
		.thenComparing(r -> r.name == null ? "" : r.name);

	private Recipe choose(String key, List<Recipe> candidates)
	{
		String pick = opt.methods.get(key);
		if (NO_MAKE.equals(pick))
		{
			return null;
		}
		if (pick != null)
		{
			for (Recipe r : candidates)
			{
				if (r.key().equals(pick))
				{
					return r;
				}
			}
		}
		return candidates.isEmpty() ? null : candidates.get(0);
	}

	private void collect(Node n, Plan plan)
	{
		if (n.fromBank > 0)
		{
			plan.fromBank.merge(n.key, n.fromBank, Long::sum);
		}
		if (n.fromOther > 0)
		{
			plan.fromOther.merge(n.key, n.fromOther, Long::sum);
		}
		if (n.shortBy > 0)
		{
			plan.shortages.merge(n.name, n.shortBy, Long::sum);
		}
		if (n.key.equals("coins"))
		{
			plan.coinsNeeded += n.need;
		}
		for (Node c : n.children)
		{
			collect(c, plan);
		}
	}

	private static boolean containsMake(Node n)
	{
		if (n.status() == Status.MAKE)
		{
			return true;
		}
		for (Node c : n.children)
		{
			if (containsMake(c))
			{
				return true;
			}
		}
		return false;
	}

	public static String normalize(String name)
	{
		return name == null ? "" : name.trim().toLowerCase(Locale.ROOT);
	}

	/**
	 * Index recipes by what they produce.
	 */
	public static Map<String, List<Recipe>> indexByOutput(List<Recipe> recipes)
	{
		Map<String, List<Recipe>> idx = new HashMap<>();
		for (Recipe r : recipes)
		{
			idx.computeIfAbsent(normalize(r.name), k -> new ArrayList<>()).add(r);
		}
		return idx;
	}
}

package com.materialplanner.recipes;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

/**
 * A single way to make something: what it produces, what it needs, and which skills.
 * Field names are the on-disk cache / seed file format.
 */
public class Recipe
{
	public static class Material
	{
		public String name;
		public int quantity;

		public Material()
		{
		}

		public Material(String name, int quantity)
		{
			this.name = name;
			this.quantity = quantity;
		}
	}

	public static class SkillReq
	{
		public String name;
		public int level;

		public SkillReq()
		{
		}

		public SkillReq(String name, int level)
		{
			this.name = name;
			this.level = level;
		}
	}

	public String name;
	public int outputQuantity = 1;
	public List<SkillReq> skills = new ArrayList<>();
	public List<Material> materials = new ArrayList<>();
	public String facility;
	public String tools;
	public boolean members;
	public String source;

	/**
	 * Display-only, set at load time (transient: not written to the cache).
	 * variant: e.g. "Sloop" when the wiki lists several same-named recipes.
	 * showMaterials: same-named recipes we couldn't label; show their materials so they can be told apart.
	 */
	public transient String variant;
	public transient boolean showMaterials;

	public String displayName()
	{
		return variant == null ? name : name + " (" + variant + ")";
	}

	public int totalMaterialQuantity()
	{
		int sum = 0;
		for (Material m : materials)
		{
			sum += m.quantity;
		}
		return sum;
	}

	public String materialsText()
	{
		StringBuilder sb = new StringBuilder();
		for (Material m : materials)
		{
			if (sb.length() > 0)
			{
				sb.append(", ");
			}
			sb.append(m.name).append(" x").append(m.quantity);
		}
		return sb.toString();
	}

	/**
	 * Second line shown under the name in lists.
	 */
	public String subtitle()
	{
		return showMaterials ? materialsText() : requirementsText();
	}

	/**
	 * Stable identity used to persist the user's selections across restarts and data refreshes.
	 */
	public String key()
	{
		StringBuilder sb = new StringBuilder(name == null ? "" : name).append('|');
		if (facility != null)
		{
			sb.append(facility);
		}
		for (Material m : materials)
		{
			sb.append('|').append(m.name).append('x').append(m.quantity);
		}
		return sb.toString();
	}

	public boolean usesSkill(String skill)
	{
		for (SkillReq s : skills)
		{
			if (s.name != null && s.name.equalsIgnoreCase(skill))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * One-line summary of requirements, e.g. "Sailing 50, Construction 26 · Shipyard".
	 */
	public String requirementsText()
	{
		StringBuilder sb = new StringBuilder();
		for (SkillReq s : skills)
		{
			if (sb.length() > 0)
			{
				sb.append(", ");
			}
			sb.append(s.name);
			if (s.level > 0)
			{
				sb.append(' ').append(s.level);
			}
		}
		if (facility != null && !facility.isEmpty())
		{
			if (sb.length() > 0)
			{
				sb.append(" · ");
			}
			sb.append(facility);
		}
		return sb.toString();
	}

	@Override
	public String toString()
	{
		return outputQuantity > 1 ? displayName() + " (x" + outputQuantity + ")" : displayName();
	}

	@Override
	public boolean equals(Object o)
	{
		return o instanceof Recipe && Objects.equals(key(), ((Recipe) o).key());
	}

	@Override
	public int hashCode()
	{
		return key().hashCode();
	}
}

package com.materialplanner.recipes;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.Writer;
import java.lang.reflect.Type;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeSet;
import java.util.concurrent.TimeUnit;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Supplies every known recipe. Sources, merged in order:
 * <ol>
 *   <li>Built-in seed recipes bundled with the plugin (always available, curated).</li>
 *   <li>The OSRS Wiki recipe database, downloaded and cached in the plugin's data directory.</li>
 * </ol>
 */
@Slf4j
public class RecipeRepository
{
	private static final String WIKI_API = "https://oldschool.runescape.wiki/api.php";
	private static final String USER_AGENT = "RuneLite Material Planner plugin";
	private static final int PAGE_SIZE = 500;
	private static final int MAX_ROWS = 40_000;
	private static final String CACHE_NAME = "recipes.json";
	private static final Type LIST_TYPE = new TypeToken<List<Recipe>>()
	{
	}.getType();

	/**
	 * Skills hidden from the skill filter: combat and spellcasting skills appear on the wiki mostly as
	 * level requirements or spell costs, not things you make. Their recipes are still searchable.
	 */
	private static final java.util.Set<String> HIDDEN_FILTER_SKILLS = new java.util.TreeSet<>(String.CASE_INSENSITIVE_ORDER);

	static
	{
		HIDDEN_FILTER_SKILLS.addAll(java.util.Arrays.asList(
			"Attack", "Strength", "Defence", "Ranged", "Magic", "Hitpoints", "Prayer"));
	}

	private static final java.util.regex.Pattern BOAT_SUFFIX = java.util.regex.Pattern.compile("\\s*\\((Raft|Skiff|Sloop)\\)$");

	private final Gson gson;
	private final OkHttpClient http;
	/** Plugin data directory, or null when it couldn't be opened (the cache is then skipped). */
	private final Filepath cacheDir;

	private volatile List<Recipe> recipes = Collections.emptyList();
	private volatile List<String> skills = Collections.emptyList();
	private volatile Map<String, List<Recipe>> byOutput = Collections.emptyMap();
	private volatile String status = "Loading recipes…";

	/**
	 * @param cacheDir the plugin's data directory from {@code Plugin#getPluginDirectory()}, or null
	 */
	public RecipeRepository(Gson gson, OkHttpClient http, Filepath cacheDir)
	{
		this.gson = gson;
		this.http = http;
		this.cacheDir = cacheDir;
	}

	public List<Recipe> getRecipes()
	{
		return recipes;
	}

	/**
	 * All recipes indexed by normalized output name, for sub-recipe expansion.
	 */
	public Map<String, List<Recipe>> getByOutput()
	{
		return byOutput;
	}

	public List<String> getSkills()
	{
		return skills;
	}

	public String getStatus()
	{
		return status;
	}

	/**
	 * Blocking; call off the client and Swing threads.
	 *
	 * @param useWiki      whether wiki data may be used at all
	 * @param refreshDays  re-download when the cache is older than this
	 * @param forceRefresh ignore cache age
	 */
	public void load(boolean useWiki, int refreshDays, boolean forceRefresh)
	{
		List<Recipe> seed = loadSeed();
		List<Recipe> wiki = Collections.emptyList();
		String wikiStatus = null;

		if (useWiki)
		{
			List<Recipe> cached = readCache();
			boolean stale = cached == null || forceRefresh
				|| System.currentTimeMillis() - cacheModified() > TimeUnit.DAYS.toMillis(refreshDays);

			if (stale)
			{
				status = "Downloading recipes from the OSRS Wiki…";
				try
				{
					List<Recipe> fresh = fetchWiki();
					if (!fresh.isEmpty())
					{
						writeCache(fresh);
						cached = fresh;
					}
				}
				catch (IOException | RuntimeException e)
				{
					log.warn("Wiki recipe download failed", e);
					wikiStatus = cached == null
						? "Wiki download failed; built-in recipes only"
						: "Wiki download failed; using cached recipes";
				}
			}
			if (cached != null)
			{
				wiki = cached;
			}
		}

		// Built-in boat-part recipes are labelled per boat; drop the wiki's unlabelled copies of them
		java.util.Set<String> seedBaseNames = new java.util.HashSet<>();
		for (Recipe r : seed)
		{
			seedBaseNames.add(BOAT_SUFFIX.matcher(r.name).replaceFirst("").toLowerCase());
		}

		Map<String, Recipe> merged = new LinkedHashMap<>();
		for (Recipe r : seed)
		{
			merged.put(r.key(), r);
		}
		for (Recipe r : wiki)
		{
			if (!seedBaseNames.contains(r.name.toLowerCase()))
			{
				merged.putIfAbsent(r.key(), r);
			}
		}
		List<Recipe> all = new ArrayList<>(merged.values());
		labelDuplicates(all);
		all.sort((a, b) -> String.CASE_INSENSITIVE_ORDER.compare(a.name, b.name));

		TreeSet<String> skillSet = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);
		for (Recipe r : all)
		{
			for (Recipe.SkillReq s : r.skills)
			{
				if (!HIDDEN_FILTER_SKILLS.contains(s.name))
				{
					skillSet.add(s.name);
				}
			}
		}

		byOutput = Planner.indexByOutput(all);
		recipes = Collections.unmodifiableList(all);
		skills = Collections.unmodifiableList(new ArrayList<>(skillSet));
		status = wikiStatus != null ? wikiStatus : String.format("%,d recipes", all.size());
	}

	/**
	 * The wiki lists raft/skiff/sloop versions of boat parts under one name. Three Sailing recipes
	 * sharing a name, each needing more materials than the last, are labelled Raft, Skiff, Sloop.
	 * Any other same-named recipes show their materials instead so they can be told apart.
	 */
	private static void labelDuplicates(List<Recipe> all)
	{
		Map<String, List<Recipe>> byName = new LinkedHashMap<>();
		for (Recipe r : all)
		{
			r.variant = null;
			r.showMaterials = false;
			byName.computeIfAbsent(r.name.toLowerCase(), k -> new ArrayList<>()).add(r);
		}
		String[] boats = {"Raft", "Skiff", "Sloop"};
		for (List<Recipe> group : byName.values())
		{
			if (group.size() < 2)
			{
				continue;
			}
			if (group.size() == 3 && group.stream().allMatch(r -> r.usesSkill("Sailing")))
			{
				List<Recipe> sorted = new ArrayList<>(group);
				sorted.sort(java.util.Comparator.comparingInt(Recipe::totalMaterialQuantity));
				if (sorted.get(0).totalMaterialQuantity() < sorted.get(1).totalMaterialQuantity()
					&& sorted.get(1).totalMaterialQuantity() < sorted.get(2).totalMaterialQuantity())
				{
					for (int i = 0; i < 3; i++)
					{
						sorted.get(i).variant = boats[i];
					}
					continue;
				}
			}
			group.forEach(r -> r.showMaterials = true);
		}
	}

	private List<Recipe> loadSeed()
	{
		try (InputStream in = RecipeRepository.class.getResourceAsStream("seed-recipes.json"))
		{
			if (in == null)
			{
				return Collections.emptyList();
			}
			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				List<Recipe> list = gson.fromJson(reader, LIST_TYPE);
				if (list == null)
				{
					return Collections.emptyList();
				}
				list.forEach(r -> r.source = "built-in");
				return list;
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not load built-in recipes", e);
			return Collections.emptyList();
		}
	}

	private Filepath cacheFile()
	{
		return cacheDir == null ? null : cacheDir.join(CACHE_NAME);
	}

	private long cacheModified()
	{
		Filepath f = cacheFile();
		try
		{
			return f != null && f.exists() ? f.getLastModifiedTime().toMillis() : 0;
		}
		catch (IOException e)
		{
			return 0;
		}
	}

	private List<Recipe> readCache()
	{
		Filepath f = cacheFile();
		if (f == null || !f.exists())
		{
			return null;
		}
		try (Reader reader = f.openBufferedReader())
		{
			return gson.fromJson(reader, LIST_TYPE);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Recipe cache unreadable, will re-download", e);
			return null;
		}
	}

	private void writeCache(List<Recipe> list)
	{
		Filepath f = cacheFile();
		if (f == null)
		{
			return;
		}
		try
		{
			cacheDir.createDirectories();
			// Write to a temp file first so a crash mid-write can't leave a corrupt cache
			Filepath tmp = cacheDir.join(CACHE_NAME + ".tmp");
			try (Writer w = tmp.openBufferedWriter())
			{
				gson.toJson(list, LIST_TYPE, w);
			}
			tmp.moveTo(f, StandardCopyOption.REPLACE_EXISTING);
		}
		catch (IOException e)
		{
			log.warn("Could not write recipe cache", e);
		}
	}

	/**
	 * Page through the wiki's "recipe" bucket, which backs the wiki's own recipe and calculator tables.
	 */
	private List<Recipe> fetchWiki() throws IOException
	{
		List<Recipe> out = new ArrayList<>();
		for (int offset = 0; offset < MAX_ROWS; offset += PAGE_SIZE)
		{
			String query = "bucket('recipe').select('page_name','production_json')"
				+ ".limit(" + PAGE_SIZE + ").offset(" + offset + ").run()";
			String url = WIKI_API + "?action=bucket&format=json&query="
				+ URLEncoder.encode(query, StandardCharsets.UTF_8.name());

			Request req = new Request.Builder().url(url).header("User-Agent", USER_AGENT).build();
			JsonArray rows;
			try (Response resp = http.newCall(req).execute())
			{
				ResponseBody body = resp.body();
				if (!resp.isSuccessful() || body == null)
				{
					throw new IOException("Wiki API returned HTTP " + resp.code());
				}
				@SuppressWarnings("deprecation")
				JsonElement root = new JsonParser().parse(body.charStream());
				rows = extractRows(root);
			}

			for (JsonElement row : rows)
			{
				if (!row.isJsonObject())
				{
					continue;
				}
				JsonObject ro = row.getAsJsonObject();
				String page = ro.has("page_name") && ro.get("page_name").isJsonPrimitive()
					? ro.get("page_name").getAsString() : null;
				Recipe r = WikiRecipeParser.parse(ro.get("production_json"), page);
				if (r != null)
				{
					out.add(r);
				}
			}

			status = String.format("Downloading recipes from the OSRS Wiki… %,d", out.size());
			if (rows.size() < PAGE_SIZE)
			{
				break;
			}
		}
		log.debug("Downloaded {} recipes from the wiki", out.size());
		return out;
	}

	/**
	 * The bucket API returns {"bucket": [...]}; fall back to the first array found in case of minor format changes.
	 */
	private static JsonArray extractRows(JsonElement root)
	{
		if (root == null || !root.isJsonObject())
		{
			throw new IllegalStateException("Unexpected wiki response");
		}
		JsonObject o = root.getAsJsonObject();
		if (o.has("error"))
		{
			throw new IllegalStateException("Wiki API error: " + o.get("error"));
		}
		if (o.has("bucket") && o.get("bucket").isJsonArray())
		{
			return o.getAsJsonArray("bucket");
		}
		for (Map.Entry<String, JsonElement> e : o.entrySet())
		{
			if (e.getValue().isJsonArray())
			{
				return e.getValue().getAsJsonArray();
			}
		}
		throw new IllegalStateException("No recipe rows in wiki response");
	}
}

package com.materialplanner.recipes;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Converts one row of the OSRS Wiki "recipe" bucket (its production_json field) into a {@link Recipe}.
 * <p>
 * The wiki's format is loosely typed (numbers are often strings, single values are sometimes not
 * wrapped in arrays), so every field is read defensively and anything unexpected is skipped.
 */
final class WikiRecipeParser
{
	private static final Pattern LEADING_INT = Pattern.compile("(\\d[\\d,]*)");

	private WikiRecipeParser()
	{
	}

	static Recipe parse(JsonElement productionJson, String pageName)
	{
		JsonObject o = asObject(productionJson);
		if (o == null)
		{
			return null;
		}

		Recipe r = new Recipe();
		r.source = "wiki";

		JsonObject output = asObject(o.get("output"));
		if (output != null)
		{
			r.name = str(output.get("name"));
			r.outputQuantity = Math.max(1, num(output.get("quantity"), 1));
		}
		if (r.name == null || r.name.isEmpty())
		{
			r.name = pageName;
		}
		if (r.name == null || r.name.isEmpty())
		{
			return null;
		}
		// Wiki page names can carry a variant suffix after '#'
		r.name = r.name.replace('#', ' ').trim();

		for (JsonElement m : asArray(o.get("materials")))
		{
			JsonObject mo = asObject(m);
			if (mo == null)
			{
				continue;
			}
			String name = str(mo.get("name"));
			if (name == null || name.isEmpty())
			{
				continue;
			}
			r.materials.add(new Recipe.Material(name, Math.max(1, num(mo.get("quantity"), 1))));
		}
		if (r.materials.isEmpty())
		{
			// Nothing to plan for (e.g. pure gathering actions)
			return null;
		}

		for (JsonElement s : asArray(o.get("skills")))
		{
			JsonObject so = asObject(s);
			if (so == null)
			{
				continue;
			}
			String name = str(so.get("name"));
			if (name != null && !name.isEmpty())
			{
				r.skills.add(new Recipe.SkillReq(capitalize(name), num(so.get("level"), 0)));
			}
		}

		r.facility = joinish(o.get("facilities"));
		r.tools = joinish(o.get("tools"));
		String members = str(o.get("members"));
		r.members = members == null || !members.equalsIgnoreCase("no");
		return r;
	}

	private static JsonObject asObject(JsonElement e)
	{
		if (e == null || e.isJsonNull())
		{
			return null;
		}
		if (e.isJsonObject())
		{
			return e.getAsJsonObject();
		}
		if (e.isJsonPrimitive() && e.getAsJsonPrimitive().isString())
		{
			try
			{
				// RuneLite ships Gson 2.8.5, which predates the static JsonParser.parseString
				@SuppressWarnings("deprecation")
				JsonElement p = new JsonParser().parse(e.getAsString());
				return p.isJsonObject() ? p.getAsJsonObject() : null;
			}
			catch (RuntimeException ex)
			{
				return null;
			}
		}
		return null;
	}

	private static JsonArray asArray(JsonElement e)
	{
		JsonArray a = new JsonArray();
		if (e == null || e.isJsonNull())
		{
			return a;
		}
		if (e.isJsonArray())
		{
			return e.getAsJsonArray();
		}
		a.add(e);
		return a;
	}

	private static String str(JsonElement e)
	{
		if (e == null || e.isJsonNull())
		{
			return null;
		}
		if (e.isJsonPrimitive())
		{
			return e.getAsString().trim();
		}
		return null;
	}

	private static String joinish(JsonElement e)
	{
		StringBuilder sb = new StringBuilder();
		for (JsonElement x : asArray(e))
		{
			String s = str(x);
			if (s != null && !s.isEmpty())
			{
				if (sb.length() > 0)
				{
					sb.append(", ");
				}
				sb.append(s);
			}
		}
		return sb.length() == 0 ? null : sb.toString();
	}

	static int num(JsonElement e, int def)
	{
		String s = str(e);
		if (s == null)
		{
			return def;
		}
		Matcher m = LEADING_INT.matcher(s);
		if (!m.find())
		{
			return def;
		}
		try
		{
			return Integer.parseInt(m.group(1).replace(",", ""));
		}
		catch (NumberFormatException ex)
		{
			return def;
		}
	}

	private static String capitalize(String s)
	{
		return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}
}

package com.materialplanner.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.swing.ImageIcon;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.http.api.item.ItemPrice;

/**
 * Item sprites by id, name → id lookup for materials the player doesn't own, and GE prices.
 */
class IconCache
{
	private final ItemManager itemManager;
	private final Map<Integer, ImageIcon> icons = new HashMap<>();
	private final Map<String, Integer> nameToId = new HashMap<>();

	IconCache(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	/**
	 * @param repaintTarget repainted once the sprite finishes loading
	 */
	ImageIcon get(int itemId, Component repaintTarget)
	{
		if (itemId <= 0)
		{
			return null;
		}
		return icons.computeIfAbsent(itemId, id ->
		{
			AsyncBufferedImage img = itemManager.getImage(id);
			if (repaintTarget != null)
			{
				img.onLoaded(repaintTarget::repaint);
			}
			return new ImageIcon(img);
		});
	}

	/**
	 * Exact-name lookup against the Grand Exchange item list. Untradeable items return -1.
	 */
	int idForName(String name)
	{
		String key = name.toLowerCase();
		return nameToId.computeIfAbsent(key, k ->
		{
			List<ItemPrice> results = itemManager.search(name);
			for (ItemPrice p : results)
			{
				if (p.getName().equalsIgnoreCase(name))
				{
					return p.getId();
				}
			}
			return -1;
		});
	}

	/**
	 * GE price each, or -1 for untradeable or unknown items.
	 */
	long price(String name)
	{
		if ("coins".equalsIgnoreCase(name))
		{
			return 1;
		}
		int id = idForName(name);
		if (id <= 0)
		{
			return -1;
		}
		long p = itemManager.getItemPrice(id);
		return p > 0 ? p : -1;
	}

	/**
	 * A small drawn "x" so the remove control doesn't depend on the font having a ✕ glyph.
	 */
	static ImageIcon removeIcon(Color color)
	{
		int s = 10;
		BufferedImage img = new BufferedImage(s, s, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(color);
		g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.drawLine(1, 1, s - 2, s - 2);
		g.drawLine(s - 2, 1, 1, s - 2);
		g.dispose();
		return new ImageIcon(img);
	}
}

